  ctx.quadraticCurveTo(x, y + h * 1.6, x - w / 2, y + h * 0.5);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = "#222";
  ctx.fillRect(x - h * 0.65, y - h * 0.1, 2, h * 1.2);
  ctx.fillRect(x + h * 0.65 - 2, y - h * 0.1, 2, h * 1.2);
